import { test } from "node:test";
import assert from "node:assert/strict";
import { agoText } from "./ago.js";

const NOW = 1_700_000_000_000;
const SECOND = 1000;
const MINUTE = 60 * SECOND;
const HOUR = 60 * MINUTE;
const DAY = 24 * HOUR;

/** The text for something that happened `age` ms before NOW. */
const at = (age) => agoText(NOW - age, NOW);

test("an at of 0 reads never, however long ago that is", () => {
  assert.equal(agoText(0, NOW), "never");
  assert.equal(agoText(0, 0), "never");
});

test("under 45 seconds reads just now, and a future time does too", () => {
  assert.equal(at(0), "just now");
  assert.equal(at(44 * SECOND), "just now");
  assert.equal(at(44_499), "just now");
  assert.equal(at(-5 * SECOND), "just now");
});

test("from 45 seconds it counts minutes, up to 45 minutes", () => {
  assert.equal(at(44_500), "1 min ago");
  assert.equal(at(45 * SECOND), "1 min ago");
  assert.equal(at(5 * MINUTE), "5 min ago");
  assert.equal(at(45 * MINUTE - SECOND), "45 min ago");
});

test("from 45 minutes it counts hours, up to 36 hours", () => {
  assert.equal(at(45 * MINUTE), "1 h ago");
  assert.equal(at(3 * HOUR), "3 h ago");
  assert.equal(at(36 * HOUR - SECOND), "36 h ago");
});

test("from 36 hours it counts days", () => {
  assert.equal(at(36 * HOUR), "2 d ago");
  assert.equal(at(2 * DAY), "2 d ago");
  assert.equal(at(30 * DAY), "30 d ago");
});
EOF
node --test src/control/dashboard/ago.test.js 2>&1 | grep -E "^# (pass|fail)|not ok|ok "

